import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`smb-cs`,heroTitle:`Automate your support questions in minutes`,heroSubtitle:`Perplexity Computer drafts replies, escalates urgent questions, and builds your support playbook — automatically.`,inputUrlCta:`Automate Customer Support`,inputUrlPlaceholder:`www.yourcompany.com`,inputUrlPrefill:`Go to {url} and analyze the business, its products, and its tone of voice. Then build me a customer support automation plan: 1) Draft reply templates for the 10 most common support questions based on the site's FAQ, product pages, and policies. 2) Create an escalation framework that flags urgent or angry tickets for human review. 3) Write a routing logic guide that categorizes incoming requests by type (billing, technical, returns, general). 4) Deliver a weekly support digest template that summarizes ticket volume, response times, and top issues.`,heroOverlaySteps:[`Scanning your site for products, policies, and FAQs`,`Drafting reply templates for your most common support questions`,`Building escalation rules for urgent and high-priority tickets`,`Reply templates, routing logic, and alert system — ready to deploy`],generatingSteps:[`Visiting {url} to extract your products, policies, and brand voice`,`Designing an agent to draft and route support replies automatically`,`Configuring escalation triggers and priority alerts for urgent tickets`,`Setting up weekly digest reporting and ticket categorization`],featureSectionTitle:`From inbox chaos to handled`,featureCardTitles:[`Connects to your support stack`,`Outputs you can send`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Zendesk, Intercom, Slack, Google Sheets — Computer plugs into your tools so tickets get triaged, replied to, and tracked in one workflow.`,`Reply templates. Escalation rules. Ticket routing logic. Weekly support digests. Computer delivers work you can plug into your inbox today.`],capabilitySectionTitle:`Your support team, on autopilot`,capabilitySectionSubtitle:`Point it at your inbox, step away, come back to handled tickets.`,capabilityCards:[{title:`Auto Replies`,description:`Computer can draft personalized responses to common questions — billing, shipping, returns, how-to — matched to your tone and policies.`},{title:`Ticket Triage`,description:`Computer can categorize incoming requests by type and urgency so nothing falls through the cracks and critical issues get seen first.`},{title:`Escalation Alerts`,description:`Computer can detect angry customers, refund requests, and edge cases — and flag them for your personal attention before they spiral.`},{title:`Connect Your Tools`,description:`Computer can read and write to Gmail, Zendesk, Intercom, Slack, and more — build workflows across your entire support stack.`},{title:`Remember & Learn`,description:`Computer can remember your products, policies, and past resolutions across sessions — so every reply gets smarter over time.`},{title:`Monitor & Alert`,description:`Computer can watch ticket volume and response times — set up a monitoring workflow that pings you when a spike or SLA breach needs attention.`}]});export{t as default};
